      <script dangerouslySetInnerHTML={{ __html: "\n(function(){\n  var box=document.getElementById('lightbox'),stage=document.getElementById('lb-stage');\n  if(!box||!stage)return;\n  function close(){box.classList.add('hidden');box.classList.remove('flex');\n    stage.innerHTML='';}\n  function open(t){\n    var src=t.getAttribute('data-lb-src'),kind=t.getAttribute('data-lb-type');\n    var title=t.getAttribute('data-lb-title')||'',desc=t.getAttribute('data-lb-desc')||'';\n    stage.innerHTML='';\n    var wrap=document.createElement('div');\n    wrap.className='flex flex-col items-center max-h-[92vh]';\n    if(kind==='video'){\n      var v=document.createElement('video');v.src=src;v.controls=true;v.autoplay=true;\n      v.playsInline=true;v.className='max-h-[82vh] max-w-full rounded-lg bg-black';\n      wrap.appendChild(v);\n    }else{\n      var i=document.createElement('img');i.src=src;\n      i.className='max-h-[82vh] max-w-full rounded-lg object-contain';\n      wrap.appendChild(i);\n    }\n    if(title||desc){\n      var cap=document.createElement('div');cap.className='mt-3 text-center max-w-3xl px-4';\n      if(title){var tt=document.createElement('div');\n        tt.className='font-bold accent-gradient text-lg';tt.textContent=title;\n        cap.appendChild(tt);}\n      if(desc){var dd=document.createElement('div');\n        dd.className='text-sm text-gray-300 mt-1';dd.textContent=desc;cap.appendChild(dd);}\n      wrap.appendChild(cap);\n    }\n    stage.appendChild(wrap);\n    box.classList.remove('hidden');box.classList.add('flex');\n  }\n  document.querySelectorAll('.lb-trigger').forEach(function(el){\n    el.addEventListener('click',function(e){e.preventDefault();open(el);});});\n  document.getElementById('lb-close').addEventListener('click',close);\n  box.addEventListener('click',function(e){if(e.target===box)close();});\n  document.addEventListener('keydown',function(e){if(e.key==='Escape')close();});\n  // 'View all N' expanders: toggle the hidden rest-rows of a media grid.\n  document.querySelectorAll('.expander').forEach(function(btn){\n    btn.addEventListener('click',function(){\n      var cls=btn.getAttribute('data-expand-target');\n      var rows=document.querySelectorAll('.'+cls);\n      var expanded=btn.getAttribute('data-expanded')==='1';\n      rows.forEach(function(r){r.classList.toggle('hidden', expanded);});\n      btn.setAttribute('data-expanded', expanded?'0':'1');\n      btn.firstChild.textContent = expanded\n        ? btn.getAttribute('data-label-more') : btn.getAttribute('data-label-less');\n    });\n  });\n  // Folder tile: reveal/hide the OPTIONAL/bonus deliverables tucked behind it.\n  document.querySelectorAll('.folder-tile').forEach(function(ft){\n    ft.addEventListener('click',function(){\n      var cls=ft.getAttribute('data-expand-target');\n      var rows=document.querySelectorAll('.'+cls);\n      var open=ft.getAttribute('data-open')==='1';\n      rows.forEach(function(r){r.classList.toggle('hidden', open);});\n      ft.setAttribute('data-open', open?'0':'1');\n      var lbl=ft.querySelector('[data-folder-label]');\n      if(lbl)lbl.textContent = open?'Open folder':'Close folder';\n    });\n  });\n  // Deck viewer: page through a multi-page document (one artifact, many slides).\n  var dv=document.getElementById('deckviewer');\n  if(dv){\n    var dvImg=document.getElementById('dv-img'),dvCounter=document.getElementById('dv-counter'),\n        dvLabel=document.getElementById('dv-label'),pages=[],idx=0;\n    function dvShow(){dvImg.src=pages[idx];dvCounter.textContent=(idx+1)+' / '+pages.length;}\n    function dvClose(){dv.classList.add('hidden');dv.classList.remove('flex');pages=[];}\n    function dvOpen(t){try{pages=JSON.parse(t.getAttribute('data-deck-pages'))||[];}catch(e){pages=[];}\n      if(!pages.length)return;idx=0;dvLabel.textContent=t.getAttribute('data-deck-label')||'';\n      dvShow();dv.classList.remove('hidden');dv.classList.add('flex');}\n    function dvStep(d){if(!pages.length)return;idx=(idx+d+pages.length)%pages.length;dvShow();}\n    document.querySelectorAll('.deck-trigger').forEach(function(el){\n      el.addEventListener('click',function(e){e.preventDefault();dvOpen(el);});});\n    document.getElementById('dv-close').addEventListener('click',dvClose);\n    document.getElementById('dv-prev').addEventListener('click',function(e){e.stopPropagation();dvStep(-1);});\n    document.getElementById('dv-next').addEventListener('click',function(e){e.stopPropagation();dvStep(1);});\n    dv.addEventListener('click',function(e){if(e.target===dv)dvClose();});\n    document.addEventListener('keydown',function(e){\n      if(dv.classList.contains('hidden'))return;\n      if(e.key==='ArrowLeft')dvStep(-1);else if(e.key==='ArrowRight')dvStep(1);\n      else if(e.key==='Escape')dvClose();});\n  }\n})();\n" }} />
